/**
 * Deterministic report generation (spec section 8.2/8.4). Pure functions of
 * (tasks.json content, database rows) — no I/O here, so generation is
 * repeatable and testable. report.mjs handles files.
 */

import { createHash } from "node:crypto";

/** sha256 of the exact tasks.json bytes (stale detection input). */
export function sourceHash(tasksJsonText) {
  return createHash("sha256").update(tasksJsonText).digest("hex").slice(0, 16);
}

/**
 * Generated-file trace check (policy: generated files trace to sources).
 * Parses the footer comment and confirms the file was machine-generated
 * from the CURRENT tasks.json hash. The event watermark is informational
 * (how fresh the projection is), not a gate: integration appends events
 * after the last report by construction, so recency can never hold at
 * merge time — freshness is restored by close-out regeneration and gated
 * separately by report.mjs --check (byte-exact re-render). A watermark
 * beyond maxEventSeq means corruption (events from the future) and fails.
 * @returns {{ok: boolean, reason?: string}}
 */
export function verifyGenerated(content, { tasksHash, maxEventSeq }) {
  const m = content.match(/tasks\.json#([0-9a-f]+) events<=(\d+)/);
  if (!m) return { ok: false, reason: "no generator footer found" };
  if (m[1] !== tasksHash) {
    return { ok: false, reason: `tasks.json moved (${m[1]} != ${tasksHash})` };
  }
  if (Number(m[2]) > maxEventSeq) {
    return { ok: false, reason: `watermark from the future (${m[2]} > ${maxEventSeq})` };
  }
  return { ok: true };
}

const GENERATED_HEADER = "<!-- GENERATED by scripts/cto/report.mjs — do not hand-edit. -->";

export function generatedFooter({ tasksHash, maxEventSeq }) {
  return `${GENERATED_HEADER}\n<!-- sources: tasks.json#${tasksHash} events<=${maxEventSeq} -->`;
}

/**
 * Byte-exact projection builder shared by report.mjs (generation),
 * report.mjs --check (staleness gate), and integrate.mjs step 4b.
 * Staleness is defined as byte inequality with a fresh render — never as
 * a watermark comparison, because integration itself appends events after
 * the last report, which would make any watermark check fail closed
 * forever. Regenerate (report.mjs) to clear staleness.
 */
export function buildProjections({ tasksText, tasks, states, events }) {
  const tasksHash = sourceHash(tasksText);
  const maxEventSeq = events.length > 0 ? events[events.length - 1].seq : 0;
  return {
    tasksHash,
    maxEventSeq,
    board: renderTasksBoard({ tasks, states, tasksHash, maxEventSeq }),
    log: renderExecutionLog({ events, tasksHash, maxEventSeq }),
  };
}

/** Human-readable task board projection. */
export function renderTasksBoard({ tasks, states, tasksHash, maxEventSeq }) {
  const lines = [
    "# Lucent — Task Board (generated)",
    "",
    GENERATED_HEADER,
    "",
    "| ID | Title | Owner | Status | Risk |",
    "| --- | --- | --- | --- | --- |",
  ];
  for (const t of tasks) {
    const st = states.get(t.id) ?? { status: "backlog" };
    const extra = st.status === "blocked" ? ` (from ${st.blocked_from}: ${st.blocked_reason})` : "";
    lines.push(`| ${t.id} | ${t.title} | ${t.owner_role} | ${st.status}${extra} | ${t.risk} |`);
  }
  lines.push("");
  for (const t of tasks) {
    const st = states.get(t.id) ?? { status: "backlog" };
    lines.push(`## ${t.id} — ${t.title}`);
    lines.push("");
    lines.push(`- status: ${st.status} | spec_rev: ${st.spec_rev ?? "?"} | owner: ${t.owner_role} | risk: ${t.risk}`);
    lines.push(`- depends on: ${(t.dependencies ?? []).join(", ") || "(none)"}`);
    lines.push(`- acceptance: ${(t.acceptance_criteria ?? []).join(" / ")}`);
    lines.push("");
  }
  lines.push(generatedFooter({ tasksHash, maxEventSeq }));
  return `${lines.join("\n")}\n`;
}

/** Human-readable execution history projection. Claims ≠ results. */
export function renderExecutionLog({ events, tasksHash, maxEventSeq }) {
  const lines = [
    "# Lucent — Execution Log (generated)",
    "",
    GENERATED_HEADER,
    "",
    "> Worker claims and independently observed results are different",
    "> things: `verification.recorded` rows carry exit codes and heads;",
    "> anything else is a claim awaiting verification.",
    "",
    "| seq | time | actor | task | attempt | action | outcome |",
    "| --- | --- | --- | --- | --- | --- | --- |",
  ];
  for (const e of events) {
    lines.push(
      `| ${e.seq} | ${new Date(e.ts).toISOString()} | ${e.actor} | ${e.task_id ?? "-"} | ${(e.attempt_id ?? "-").slice(0, 13)} | ${e.action} | ${e.outcome} |`,
    );
  }
  lines.push("");
  lines.push(generatedFooter({ tasksHash, maxEventSeq }));
  return `${lines.join("\n")}\n`;
}

/** Founder report (§13): only what the records support. */
export function renderFounderReport({ tasks, states, events, pendingApprovals, integratedCommit, remotePushed, tasksHash, maxEventSeq }) {
  const byStatus = new Map();
  for (const t of tasks) {
    const st = (states.get(t.id) ?? { status: "backlog" }).status;
    if (!byStatus.has(st)) byStatus.set(st, []);
    byStatus.get(st).push(t.id);
  }
  const failures = events.filter((e) => ["fail", "timeout", "refused", "error"].includes(e.outcome));
  const lines = [
    "# Founder Report (generated)",
    "",
    GENERATED_HEADER,
    "",
    "## Requested",
    "See task specs in tasks.json (canonical).",
    "",
    "## Completed",
    `- done: ${(byStatus.get("done") ?? []).join(", ") || "(none)"}`,
    `- verified: ${(byStatus.get("verified") ?? []).join(", ") || "(none)"}`,
    "",
    "## Repository changes",
    `- integrated commit: ${integratedCommit ?? "(none this run)"}`,
    `- remote push occurred: ${remotePushed ? "YES" : "NO"}`,
    "",
    "## Verification (actual results, including failures)",
    ...(failures.length === 0
      ? ["- no recorded failures in this window"]
      : failures.slice(0, 50).map((e) => `- seq ${e.seq}: ${e.action} on ${e.task_id} → ${e.outcome}`)),
    "",
    "## Remaining and blocked",
    `- blocked: ${(byStatus.get("blocked") ?? []).join(", ") || "(none)"}`,
    `- in progress / review / integration: ${["in_progress", "review", "integration"].flatMap((s) => byStatus.get(s) ?? []).join(", ") || "(none)"}`,
    "",
    "## Risks and unverified claims",
    "- any status below verified is a claim, not an accepted result",
    "- evidence binds to a specific HEAD; source moves invalidate it (see verification records)",
    "",
    "## Decisions / approvals required",
    ...(pendingApprovals.length === 0 ? ["- (none)"] : pendingApprovals.map((a) => `- ${a}`)),
    "",
    generatedFooter({ tasksHash, maxEventSeq }),
  ];
  return `${lines.join("\n")}\n`;
}
